			u64 = (u64 << 0x08) + uint64(src[oldOffset+3])
		}
		dstObj.SetUint(u64)
		newOffset = oldOffset + 4
	case reflect.Int64:
		if LittleEndian == byteOrder {
			u64 = uint64(src[oldOffset+7])
			u64 = (u64 << 0x08) + uint64(src[oldOffset+6])
